import{_ as n,o as h,c as i,a2 as c}from"./chunks/framework.BBd5PKnH.js";const m=JSON.parse('{"title":"The Practicing Stoic — Ghi chú phần mở đầu sách","description":"","frontmatter":{},"headers":[],"relativePath":"philosophy/practicing-stoicism/intro/00-muc-luc.md","filePath":"philosophy/practicing-stoicism/intro/00-muc-luc.md"}'),o={name:"philosophy/practicing-stoicism/intro/00-muc-luc.md"};function a(g,t,r,l,u,e){return h(),i("div",null,[...t[0]||(t[0]=[c('<h1 id="the-practicing-stoic-—-ghi-chu-phan-mo-đau-sach" tabindex="-1">The Practicing Stoic — Ghi chú phần mở đầu sách <a class="header-anchor" href="#the-practicing-stoic-—-ghi-chu-phan-mo-đau-sach" aria-label="Permalink to &quot;The Practicing Stoic — Ghi chú phần mở đầu sách&quot;">​</a></h1><p>Sách: <em>The Practicing Stoic</em> — Ward Farnsworth Phạm vi: Lời tựa (Preface) + Dẫn nhập (Introduction) Cách viết: giải thích lại bằng tiếng Việt, kèm ví dụ đời thường và insight tâm lý — không phải bản dịch nguyên văn.</p><h2 id="cac-file" tabindex="-1">Các file <a class="header-anchor" href="#cac-file" aria-label="Permalink to &quot;Các file&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Nội dung</th></tr></thead><tbody><tr><td><code>01-loi-tua.md</code></td><td>Lời tựa: Khắc kỷ thật sự là gì, vì sao viết cuốn này, cách sách chọn lọc, ý nghĩa tên sách, phản hồi các lời chê</td></tr><tr><td><code>02-dan-nhap.md</code></td><td>Dẫn nhập: 9 ý tóm tắt toàn bộ tư tưởng của sách (kèm chương tương ứng)</td></tr><tr><td><code>03-ap-dung-va-insight.md</code></td><td>Hỏi đáp áp dụng thực tế + insight tâm lý học hiện đại (mô hình ABC, niềm tin gốc, giá trị bản thân có điều kiện…)</td></tr><tr><td><code>04-tu-vung.md</code></td><td>Từ vựng tiếng Anh đáng nhớ, gom theo phần</td></tr></tbody></table><h2 id="tom-ca-phan-mo-đau-trong-5-cau" tabindex="-1">Tóm cả phần mở đầu trong 5 câu <a class="header-anchor" href="#tom-ca-phan-mo-đau-trong-5-cau" aria-label="Permalink to &quot;Tóm cả phần mở đầu trong 5 câu&quot;">​</a></h2><ol><li>Khắc kỷ gốc <strong>không phải</strong> là lạnh lùng, cam chịu — mà là một hệ thống thực tế giúp sống khôn ngoan và bình an.</li><li>Ta <strong>không phản ứng với sự việc</strong>, mà với <strong>câu chuyện mình tự kể</strong> về sự việc.</li><li>Hãy đặt hạnh phúc vào <strong>thứ mình kiểm soát được</strong> (suy nghĩ, hành động), buông bám chấp vào phần còn lại.</li><li>Thay đổi suy nghĩ bằng <strong>lý lẽ</strong> (phân tích) và bằng <strong>đổi góc nhìn</strong> (hình ảnh).</li><li>Khắc kỷ là <strong>luyện tập</strong> như võ thuật, không phải lý thuyết để ngưỡng mộ — và ai cũng chỉ là &quot;đang tập&quot;.</li></ol><h2 id="y-tuong-carousel-nay-ra-trong-luc-đoc" tabindex="-1">Ý tưởng carousel nảy ra trong lúc đọc <a class="header-anchor" href="#y-tuong-carousel-nay-ra-trong-luc-đoc" aria-label="Permalink to &quot;Ý tưởng carousel nảy ra trong lúc đọc&quot;">​</a></h2><ul><li>&quot;Ngôi đền rút một cột vẫn đứng&quot; — Khắc kỷ không cần tôn giáo vẫn đứng vững</li><li>&quot;Cùng đỉnh núi, khác sườn leo&quot; — Khắc kỷ và các truyền thống tâm linh</li><li>&quot;Vệ sinh tâm lý&quot; — đánh răng cho đầu óc</li><li>&quot;Bạn là người Khắc kỷ à? — Không, mình chỉ đang tập thôi&quot;</li><li>&quot;Phản ứng của cựu binh&quot; — bình tĩnh như đã trải qua lần thứ 1000</li><li>&quot;Bánh xe hamster&quot; — niềm vui tự bịa ra để chạy mãi</li><li>&quot;Trốn <em>vào</em> thực tế, không phải trốn <em>khỏi</em> thực tế&quot;</li><li>&quot;Không dính mắc ≠ thờ ơ&quot;</li><li>&quot;Cảm xúc của bạn đã bị văn hóa cài đặt sẵn&quot;</li><li>&quot;Cùng bị chê, sao người giận, người buồn, người chẳng sao?&quot; (giải mã hiện tượng)</li></ul>',8)])])}const d=n(o,[["render",a]]);export{m as __pageData,d as default};
